	"os"

	"example.com/sysprobe/internal/sysinfo"
)

func main() {
	asJSON := flag.Bool("json", false, "emit machine-readable JSON")
	flag.Parse()

	info, err := sysinfo.Gather()
	if err != nil {
		fmt.Fprintln(os.Stderr, "sysprobe:", err)
		os.Exit(1)
	}

