package sysinfo

import "bytes"

// utsName converts a NUL-terminated utsname(2) character array to a Go string.
// The standard library does not expose uname(2) at all, so the fields are
// decoded by hand from the array x/sys returns.
func utsName(b []byte) string {
	if i := bytes.IndexByte(b, 0); i >= 0 {
		b = b[:i]
	}
	return string(b)
}

//go:build linux

package sysinfo

import (
	"strconv"
	"strings"

	"golang.org/x/sys/unix"
)

// Gather reports Linux system information. It uses uname(2) for identity and
// sysinfo(2) for uptime, load average and physical memory; neither call is
// wrapped by the standard library.
func Gather() (Info, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return Info{}, err
	}

	info := Info{
		Hostname: utsName(uts.Nodename[:]),
		Kernel:   strings.TrimSpace(utsName(uts.Release[:]) + " " + utsName(uts.Version[:])),
		Arch:     utsName(uts.Machine[:]),
		Uptime:   -1,
		Details:  map[string]string{},
	}

	var si unix.Sysinfo_t
	if err := unix.Sysinfo(&si); err != nil {
		return info, err
	}

	info.Uptime = si.Uptime
	info.Memory = si.Totalram * uint64(si.Unit)
	info.Details["loadavg"] = strings.TrimSpace(strings.Join([]string{
		strconv.FormatUint(si.Loads[0], 10),
		strconv.FormatUint(si.Loads[1], 10),
		strconv.FormatUint(si.Loads[2], 10),
	}, " "))
	info.Details["procs"] = strconv.FormatUint(uint64(si.Procs), 10)

	return info, nil
}

//go:build darwin

package sysinfo

import (
	"strconv"
	"strings"
	"time"

	"golang.org/x/sys/unix"
)

// Gather reports macOS system information. It uses uname(2) for identity and
// the sysctl(3) MIB for uptime, memory and hardware details; the standard
// library exposes neither.
func Gather() (Info, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return Info{}, err
	}

	info := Info{
		Hostname: utsName(uts.Nodename[:]),
		Kernel:   strings.TrimSpace(utsName(uts.Release[:]) + " " + utsName(uts.Version[:])),
		Arch:     utsName(uts.Machine[:]),
		Uptime:   -1,
		Details:  map[string]string{},
	}

	if mem, err := unix.SysctlUint64("hw.memsize"); err == nil {
		info.Memory = mem
	}
	if boot, err := unix.SysctlTimeval("kern.boottime"); err == nil {
		info.Uptime = time.Now().Unix() - boot.Sec
	}
	if cpus, err := unix.SysctlUint32("hw.ncpu"); err == nil {
		info.Details["cpus"] = strconv.FormatUint(uint64(cpus), 10)
	}
	if model, err := unix.Sysctl("hw.model"); err == nil {
		info.Details["model"] = model
	}

	return info, nil
}

//go:build !linux && !darwin && !windows

package sysinfo

// Gather reports ErrUnsupported on platforms without a syscall binding.
func Gather() (Info, error) {
	return Info{}, ErrUnsupported
}

